/* Room III: shared navigation and turquoise workspace across all three modes.
   Retain the existing editor, installation canvas and enhancer machinery. */
.nd-room-shell {padding-bottom:16px}
.nd-room-shell > .nd-shared-heading {margin-bottom:14px;padding-bottom:12px;border-bottom:1px solid var(--nd-line)}
.nd-room-shell .nd-heading-copy {min-width:0}
.nd-room-shell .nd-heading-copy h2 {font-family:ui-sans-serif,system-ui,sans-serif;font-size:23px;font-weight:600;letter-spacing:-.02em;color:#e4f5f1}
.nd-room-shell .nd-heading-copy p {font-size:11px;color:#aac6c4;margin-top:4px}
.nd-room-shell .nd-modes {flex-wrap:wrap;align-items:center;justify-content:flex-end}
.nd-room-shell .nd-modes button {border:1px solid #36545a;background:#12272e;color:#b7cfcf;min-height:34px;padding:6px 12px;white-space:nowrap}
.nd-room-shell .nd-modes .is-active {background:#28514e;border-color:#83d5c9;color:#e5fff8}
.nd-room-shell .nd-designer-body {min-width:0}
.nd-room-shell .nd-designer-body .nd-toolbar {border-top:0;padding-top:0}
/* Legacy Installation and Enhancer get the same chrome; no second heading or tab row. */
.nd-legacy-body .nd-legacy-root {max-width:none;margin:0;min-width:0}
.nd-legacy-card {background:transparent!important;border:0!important;padding:0!important}
.nd-legacy-old-title {display:none!important}
.nd-legacy-tab-duplicates {display:none!important}
.nd-legacy-meta {display:grid!important;grid-template-columns:minmax(0,1fr) auto;gap:8px 14px;align-items:center;padding:0 0 11px!important;margin:0;border-color:#31474d!important}
.nd-legacy-info {display:flex!important;flex-wrap:wrap;align-items:center;gap:9px;min-width:0;background:#102b31!important;border:1px solid #3a6869!important;color:#bde6dd!important;border-radius:8px!important;padding:7px 10px!important}
.nd-legacy-info > div {margin:0!important;font-size:11px!important}
.nd-legacy-info > div:nth-child(2) {font-size:15px!important;font-weight:600!important;color:#def6ec!important}
.nd-legacy-info > div:nth-child(3) {font-size:10px!important;color:#94bdb9!important}
.nd-legacy-tools {display:flex!important;flex-wrap:wrap;gap:6px!important;align-items:center;justify-content:flex-end}
.nd-legacy-tools > button {min-height:34px!important;padding:5px 11px!important;border:1px solid #36545a!important;background:#152d34!important;color:#cbe0df!important;border-radius:7px!important;font-size:11px!important;letter-spacing:0!important}
.nd-legacy-tools > button:hover {background:#24454b!important;border-color:#78d9d0!important}
.nd-legacy-meta > div:last-child {grid-column:1/-1;margin:0!important;gap:8px!important}
.nd-legacy-meta > div:last-child > div:first-child {color:#a7e0d4!important}
.nd-legacy-body > .nd-legacy-root .nd-legacy-stage {border:1px solid #344e55!important;border-radius:12px;background:#0b1920!important;overflow:hidden}
.nd-legacy-body .border-neutral-800 {border-color:#30444b!important}
.nd-legacy-body .bg-neutral-950 {background-color:#0c1c23!important}
.nd-legacy-body .bg-black {background-color:#101e26!important}
.nd-legacy-body .text-fuchsia-300,.nd-legacy-body .text-fuchsia-100 {color:#92dace!important}
.nd-legacy-body .border-fuchsia-400 {border-color:#77cfbe!important}
.nd-legacy-body .bg-fuchsia-950\/30 {background:#173b3b!important}
.nd-legacy-body input[type="range"] {accent-color:#80cbbf}
.nd-legacy-body .nd-legacy-card > div:last-child {margin-top:12px!important}
.nd-legacy-body .nd-legacy-stage canvas {border-radius:12px}
@media(max-width:820px) {
  .nd-room-shell > .nd-shared-heading {flex-direction:column;align-items:stretch}
  .nd-room-shell .nd-modes {justify-content:flex-start;gap:5px}
  .nd-room-shell .nd-heading-copy h2 {font-size:21px}
  .nd-legacy-meta {grid-template-columns:minmax(0,1fr)}
  .nd-legacy-tools {justify-content:flex-start}
  .nd-legacy-info > div:nth-child(3) {display:none}
}
